/**
 * Writes the compiled 2D physics into a TypeScript module as base64, so the engine loads it with no file
 * to serve and no loader to configure: in a browser, in a desktop shell and in a test alike.
 */
const [from, to] = process.argv.slice(2);
if (from === undefined || to === undefined) throw new Error('usage: bun embed_wasm.ts <in.wasm> <out.ts>');
const bytes = new Uint8Array(await Bun.file(from).arrayBuffer());
await Bun.write(to, [
    '// Generated by native/physics2d/build.sh: Box2D v3.1.1 and naca_physics2d.c, compiled. Do not edit.',
    '',
    '/**',
    ' * The 2D physics WebAssembly, as base64.',
    ' *',
    ' * @internal',
    ' */',
    `export const BOX2D_WASM = '${Buffer.from(bytes).toString('base64')}';`,
    '',
].join('\n'));
console.log(`${to}: ${bytes.length} bytes of WebAssembly`);
